        it["customer"] = Customer(body.get("firstName", ""), body.get("lastName", ""),
                                  body.get("email", ""), body.get("phone", ""),
                                  address.get("street1", ""), address.get("postalCode", ""),
                                  address.get("city", ""), address.get("region", ""),
                                  address.get("countryCode", ""))
